// Traitement de la réponse OpenAI et sélection du template
const aiResponse = $input.item.json.text;
const formData = $node["Formulaire IA"].json;
const binaryData = $node["Formulaire IA"].binary;

// Parser la réponse JSON d'OpenAI
let analysis;
try {
  const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
  analysis = JSON.parse(cleanResponse);
} catch (e) {
  // Fallback si parsing échoue
  console.log('Parsing failed:', e.message);
  analysis = {
    title: 'Titre de l\'article',
    subtitle: '',
    body: formData.contenu || ''
  };
}

// Compter les images
const imageCount = Object.keys(binaryData || {}).length;
console.log('Images détectées:', imageCount);
console.log('Binary data keys:', Object.keys(binaryData || {}));

// Sélectionner le template
let template;
if (imageCount === 1) {
  template = 'template-mag-simple-1808';
} else if (imageCount >= 3) {
  template = 'template-mag-simple-2-1808';
} else {
  template = 'template-mag-simple-1808'; // défaut
}

// Retourner les données structurées
return {
  // Données analysées par l'IA
  ai_analysis: {
    title: analysis.title,
    subtitle: analysis.subtitle,
    body: analysis.body
  },
  // Données de template
  template_selection: {
    template: template,
    image_count: imageCount,
    reason: imageCount === 1 ? '1 image détectée' : imageCount >= 3 ? imageCount + ' images détectées' : 'Défaut'
  },
  // Données originales
  original_content: formData.contenu,
  // Debug
  debug: {
    ai_raw_response: aiResponse,
    binary_keys: Object.keys(binaryData || {})
  }
};

