const response = $input.item.json;
const aiData = $node["Traitement IA & Template"].json;

if (response.success) {
  return {
    status: 'success',
    message: '🎉 Document créé avec l\'IA !',
    details: {
      template_used: aiData.template_selection.template,
      template_reason: aiData.template_selection.reason,
      image_count: aiData.template_selection.image_count,
      ai_analysis: {
        title: aiData.ai_analysis.title,
        subtitle: aiData.ai_analysis.subtitle,
        body_preview: aiData.ai_analysis.body.substring(0, 100) + '...'
      }
    },
    project_id: response.project_id,
    download_url: `http://127.0.0.1:5002/api/download/${response.project_id}`
  };
} else {
  return {
    status: 'error',
    message: '❌ Erreur: ' + (response.error || 'Erreur inconnue'),
    ai_data: aiData,
    debug_info: response
  };
}
